<template>
  <div class="modelOperationsPage">
    <cruioHeader />
    <main class="pageContent">
      <header class="adminHeading"><div><h1>{{ providerView ? '供应商' : '模型目录' }}</h1><p>{{ providerView ? '渠道、服务区域及所属模型；添加供应商时一并配置首个模型' : '按类型、供应商和发布状态管理模型配置' }}</p></div><div class="headingActions"><button class="adminButton" type="button" :disabled="loading" @click="loadData()">刷新</button><button v-if="canManage" class="adminButton primary" type="button" :disabled="savingRevision || savingAction" @click="openEditor()">{{ providerView ? '添加供应商与模型' : '添加模型' }}</button></div></header>
      <p v-if="pageError" class="feedback error" role="alert">{{ pageError }}</p><p v-if="pageMessage" class="feedback success" role="status">{{ pageMessage }}</p>
      <p v-if="!authorized && !loading" class="feedback">当前账号没有查看模型目录的权限。</p>
      <template v-else-if="authorized">
        <p v-if="!canManage && !loading" class="accessNote">当前为只读目录。编辑和发布需要模型运营岗位。<router-link to="/admin/users">管理岗位授权</router-link></p>
        <form class="adminToolbar" @submit.prevent><label>检索<input v-model.trim="modelQuery" type="search" placeholder="供应商或模型 ID" /></label><template v-if="!providerView"><label>类型<select v-model="operationFilter"><option value="">全部类型</option><option value="image.generate">图片</option><option value="video.generate">视频</option></select></label><label>供应商<select v-model="providerFilter"><option value="">全部供应商</option><option v-for="provider in providers" :key="provider.id" :value="provider.id">{{ provider.name }}</option></select></label><label>状态<select v-model="publicationFilter"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">未发布</option></select></label><label>版本<select v-model="versionFilter"><option value="current">当前版本</option><option value="all">全部历史</option></select></label></template></form>
        <div v-if="providerView" class="adminTableWrap"><table><thead><tr><th>供应商</th><th>渠道 / 服务区域</th><th>模型类型</th><th>当前模型</th><th>操作</th></tr></thead><tbody><tr v-for="provider in filteredProviders" :key="provider.id"><td>{{ provider.name }}<span class="secondaryText">{{ provider.id }}</span></td><td>{{ provider.channels.join('、') }}<span class="secondaryText">{{ provider.regions.join('、') }}</span></td><td>{{ provider.types.map(operationLabel).join('、') }}</td><td>{{ provider.count }} 个<span class="secondaryText">{{ provider.published }} 个已发布</span></td><td><router-link class="adminTextLink" :to="{ path: '/admin/models', query: { provider: provider.id } }">查看模型</router-link></td></tr><tr v-if="!filteredProviders.length"><td colspan="5" class="adminEmpty">{{ loading ? '正在读取供应商…' : '暂无匹配的供应商' }}</td></tr></tbody></table></div>
        <div v-else class="adminTableWrap"><table><thead><tr><th>模型 / 版本</th><th>供应商</th><th>类型</th><th>配置版本</th><th>发布状态</th><th>积分价格</th><th>操作</th></tr></thead><tbody><tr v-for="model in filteredModels" :key="model.id"><td>{{ model.modelId }}<span class="secondaryText">{{ model.modelVersion }}</span></td><td>{{ model.providerLabel }}<span class="secondaryText">{{ model.region }}</span></td><td>{{ operationLabel(model.operation) }}</td><td>v{{ model.configVersion }}<span class="secondaryText">{{ model.isCurrent ? '当前版本' : '历史版本' }}</span></td><td><span class="statusText" :class="model.published && model.isCurrent ? 'active' : ''">{{ !model.isCurrent ? '历史' : model.published ? '已发布' : '未发布' }}</span></td><td>{{ model.creditPrice === null ? '未配置' : `${model.creditPrice} 点` }}</td><td><button class="adminTextLink" type="button" :disabled="savingRevision || savingAction" @click="openEditor(model)">{{ canManage && model.isCurrent ? '管理' : '详情' }}</button></td></tr><tr v-if="!filteredModels.length"><td colspan="7" class="adminEmpty">{{ loading ? '正在读取模型…' : '暂无匹配的模型' }}</td></tr></tbody></table></div>
        <p class="catalogCount">共 {{ providerView ? filteredProviders.length : filteredModels.length }} {{ providerView ? '个供应商' : '条模型配置' }}</p>
        <section v-if="editorOpen && selectedModel && (!canManage || !selectedModel.isCurrent)" ref="revisionPanel" class="panel modelDetail" tabindex="-1"><header class="sectionHeading"><h2>{{ selectedModel.modelId }} · 配置 v{{ selectedModel.configVersion }}</h2><button class="adminButton" type="button" @click="editorOpen = false">关闭</button></header><dl><div><dt>供应商</dt><dd>{{ selectedModel.providerLabel }}</dd></div><div><dt>服务区域</dt><dd>{{ selectedModel.region }}</dd></div><div><dt>接口地址</dt><dd>{{ selectedModel.endpoint }}</dd></div><div><dt>凭据引用</dt><dd>{{ selectedModel.credentialRef }}</dd></div></dl><details><summary>能力配置</summary><pre>{{ JSON.stringify(selectedModel.capabilities, null, 2) }}</pre></details></section>
        <section v-if="editorOpen && canManage && (!selectedModel || selectedModel.isCurrent)" ref="revisionPanel" class="panel revisionPanel" tabindex="-1" aria-labelledby="revisionHeading">
          <header class="sectionHeading"><div><h2 id="revisionHeading">{{ revisionForm.baseRevisionId ? "修订模型配置" : "添加模型" }}</h2><p>保存为未发布版本。已发布模型的修订生效后，需要重新发布。</p></div><button class="adminButton" type="button" :disabled="savingRevision || savingAction" @click="editorOpen = false">关闭</button></header>
          <p v-if="revisionForm.baseRevisionId && selectedModel?.published" class="impactNotice">此修订当前已发布。保存后会立即停用当前映射；新修订发布前，使用该映射的生成请求将不可用。</p>
          <form class="revisionForm" @submit.prevent="saveRevision">
            <div class="formGrid">
              <label>供应商 ID<input v-model.trim="revisionForm.providerId" required maxlength="64" autocomplete="off" :readonly="Boolean(revisionForm.baseRevisionId)" placeholder="例如 openai" list="providerIds" /><datalist id="providerIds"><option v-for="provider in providers" :key="provider.id" :value="provider.id">{{ provider.name }}</option></datalist></label>
              <label>供应商名称<input v-model.trim="revisionForm.providerLabel" required maxlength="120" /></label>
              <label>渠道<select v-model="revisionForm.channelKind"><option value="official">官方渠道</option><option value="compatible">兼容渠道</option></select></label>
              <label>服务区域<input v-model.trim="revisionForm.region" required maxlength="120" /></label>
              <label>适配协议<select v-model="revisionForm.protocol" @change="syncProtocol"><option value="openai_images">OpenAI 图像</option><option value="volcengine_ark_video">火山方舟视频</option></select></label>
              <label>接口地址<input v-model.trim="revisionForm.endpoint" type="url" required maxlength="500" /></label>
              <label>凭据环境变量名<input v-model.trim="revisionForm.credentialRef" required maxlength="128" autocomplete="off" placeholder="例如 CRUIO_OPENAI_API_KEY" /></label>
              <label>外部模型 ID<input v-model.trim="revisionForm.modelId" required maxlength="200" :readonly="Boolean(revisionForm.baseRevisionId)" /></label>
              <label>模型版本<input v-model.trim="revisionForm.modelVersion" required maxlength="120" :readonly="Boolean(revisionForm.baseRevisionId)" /></label>
              <label>积分价格<input :value="revisionForm.creditPrice ?? ''" type="number" min="1" step="1" @input="updateCreditPrice" /></label>
              <label class="wideField">能力配置 JSON<textarea v-model="revisionForm.capabilitiesJson" required rows="4" spellcheck="false" /></label>
              <label class="wideField">成本依据 JSON<textarea v-model="revisionForm.costReferenceJson" required rows="3" spellcheck="false" /></label>
              <label class="wideField">当前密码<input v-model="revisionForm.currentPassword" type="password" autocomplete="current-password" required minlength="8" maxlength="256" /></label>
            </div>
            <button class="primaryButton" type="submit" :disabled="savingRevision">{{ savingRevision ? "正在保存…" : revisionForm.baseRevisionId && selectedModel?.published ? "保存修订并停用当前映射" : "保存为未发布版本" }}</button>
          </form>
        </section>
        <section v-if="editorOpen && canManage && selectedModel?.isCurrent" class="panel actionPanel" aria-labelledby="actionHeading">
          <header class="sectionHeading"><div><h2 id="actionHeading">发布与停用</h2><p>发布或停用会创建新的服务端配置版本；陈旧版本会被拒绝。</p></div></header>
          <form class="actionForm" @submit.prevent="prepareAction">
            <label>当前映射<select v-model="actionForm.modelRevisionId" required><option value="" disabled>选择当前映射</option><option v-for="model in currentModels" :key="model.id" :value="model.id">{{ model.providerLabel }} · {{ model.modelId }} · v{{ model.configVersion }} · {{ model.published ? "已发布" : "未发布" }}</option></select></label>
            <label>操作理由<textarea v-model.trim="actionForm.reason" required maxlength="500" rows="2" /></label>
            <label>当前密码<input v-model="actionForm.currentPassword" type="password" autocomplete="current-password" required minlength="8" maxlength="256" /></label>
            <div class="actionButtons"><button class="primaryButton" type="submit" :disabled="savingAction || !actionForm.modelRevisionId || !actionForm.reason.trim() || !actionForm.currentPassword">{{ actionForm.action === "publish" ? "核对并发布" : "核对并停用" }}</button><button class="secondaryButton" type="button" :disabled="savingAction" @click="toggleAction">切换为{{ actionForm.action === "publish" ? "停用" : "发布" }}</button></div>
          </form>
        </section>
      </template>
      <div v-if="showConfirm" class="modalBackdrop" @click.self="closeConfirm"><section ref="dialogRef" class="confirmDialog" role="dialog" aria-modal="true" aria-labelledby="confirmHeading" tabindex="-1" @keydown="trapFocus" @keydown.esc.prevent.stop="closeConfirm"><h2 id="confirmHeading">确认{{ actionSnapshot?.action === "publish" ? "发布" : "停用" }}模型映射</h2><p v-if="actionSnapshot">{{ actionSnapshot.model.providerLabel }} · {{ actionSnapshot.model.modelId }} · 当前配置 v{{ actionSnapshot.model.configVersion }}</p><p>{{ actionSnapshot?.reason }}</p><p v-if="actionError" class="feedback error" role="alert">{{ actionError }}</p><label>当前密码<input ref="passwordInput" v-model="actionForm.currentPassword" type="password" autocomplete="current-password" required minlength="8" maxlength="256" :disabled="savingAction" /></label><div class="dialogActions"><button class="secondaryButton" type="button" :disabled="savingAction" @click="closeConfirm">返回修改</button><button class="primaryButton" type="button" :disabled="savingAction || !actionForm.currentPassword" @click="runModelAction">{{ savingAction ? "正在提交…" : `确认${actionSnapshot?.action === "publish" ? "发布" : "停用"}` }}</button></div></section></div>
    </main>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import cruioHeader from "@/components/cruioHeader.vue";
import { api } from "@/lib/cruioApi";
import { useCruioSession } from "@/stores/cruioSession";

type Model = { id: string; providerId: string; providerLabel: string; channelKind: "official" | "compatible"; region: string; protocol: "openai_images" | "volcengine_ark_video"; endpoint: string; credentialRef: string; modelId: string; modelVersion: string; operation: "image.generate" | "video.generate"; capabilities: Record<string, unknown>; costReference: Record<string, unknown>; creditPrice: number | null; verifiedAt: string; published: boolean; configVersion: number; isCurrent: boolean };
type ModelData = { models: Model[]; canManage: boolean };
type ActionSnapshot = { action: "publish" | "pause"; model: Model; reason: string };
const route = useRoute(); const router = useRouter(); const session = useCruioSession();
const loading = ref(true); const authorized = computed(() => session.hasRole("admin", true) || session.hasRole("modelOperator", true));
const canManage = ref(false);
const providerView = computed(() => route.name === "adminProviders");
const modelQuery = ref("");
const providerFilter = ref(typeof route.query.provider === "string" ? route.query.provider : "");
const operationFilter = ref("");
const publicationFilter = ref("");
const versionFilter = ref("current");
const editorOpen = ref(false);
const revisionPanel = ref<HTMLElement | null>(null);
const models = ref<Model[]>([]); const selectedModel = ref<Model | null>(null); const pageError = ref(""); const pageMessage = ref(""); const actionError = ref(""); const savingRevision = ref(false); const savingAction = ref(false); const showConfirm = ref(false); const actionSnapshot = ref<ActionSnapshot | null>(null); const dialogRef = ref<HTMLElement | null>(null); const passwordInput = ref<HTMLInputElement | null>(null); const returnFocus = ref<HTMLElement | null>(null);
const revisionForm = reactive({ baseRevisionId: "", providerId: "", providerLabel: "", channelKind: "official" as "official" | "compatible", region: "", protocol: "openai_images" as "openai_images" | "volcengine_ark_video", endpoint: "https://api.openai.com/v1", credentialRef: "", modelId: "", modelVersion: "v1", operation: "image.generate" as "image.generate" | "video.generate", creditPrice: null as number | null, capabilitiesJson: "{\n  \"inputs\": [\"text\"],\n  \"outputs\": [\"image\"]\n}", costReferenceJson: "{}", currentPassword: "" });
const actionForm = reactive({ action: "publish" as "publish" | "pause", modelRevisionId: "", reason: "", currentPassword: "" });
const currentModels = computed(() => models.value.filter(model => model.isCurrent));
const providers = computed(() => {
  const grouped = new Map<string, { id: string; name: string; channels: string[]; regions: string[]; types: string[]; count: number; published: number }>();
  for (const model of currentModels.value) {
    const provider = grouped.get(model.providerId) ?? { id: model.providerId, name: model.providerLabel, channels: [], regions: [], types: [], count: 0, published: 0 };
    const channel = model.channelKind === "official" ? "官方" : "兼容渠道";
    if (!provider.channels.includes(channel)) provider.channels.push(channel);
    if (!provider.regions.includes(model.region)) provider.regions.push(model.region);
    if (!provider.types.includes(model.operation)) provider.types.push(model.operation);
    provider.count++; if (model.published) provider.published++;
    grouped.set(model.providerId, provider);
  }
  return [...grouped.values()];
});
const filteredProviders = computed(() => providers.value.filter(provider => `${provider.id} ${provider.name}`.toLowerCase().includes(modelQuery.value.toLowerCase())));
const filteredModels = computed(() => models.value.filter(model => (versionFilter.value === "all" || model.isCurrent)
  && (!providerFilter.value || model.providerId === providerFilter.value)
  && (!operationFilter.value || model.operation === operationFilter.value)
  && (!publicationFilter.value || model.published === (publicationFilter.value === "published"))
  && `${model.modelId} ${model.providerId} ${model.providerLabel}`.toLowerCase().includes(modelQuery.value.toLowerCase())));
async function openEditor(model?: Model) {
  if (model) selectModel(model);
  else {
    resetRevision();
    const provider = currentModels.value.find(item => item.providerId === providerFilter.value);
    if (provider) Object.assign(revisionForm, { providerId: provider.providerId, providerLabel: provider.providerLabel, channelKind: provider.channelKind, region: provider.region, endpoint: provider.endpoint, credentialRef: provider.credentialRef, protocol: provider.protocol, operation: provider.operation, capabilitiesJson: JSON.stringify(provider.capabilities, null, 2) });
  }
  editorOpen.value = true;
  await nextTick(); revisionPanel.value?.focus();
}
function operationLabel(value: string) { return value === "image.generate" ? "图片生成" : value === "video.generate" ? "视频生成" : "模型操作"; }
function updateCreditPrice(event: Event) { const value = (event.target as HTMLInputElement).value; revisionForm.creditPrice = value === "" ? null : Number(value); }
function syncProtocol() { const video = revisionForm.protocol === "volcengine_ark_video"; revisionForm.operation = video ? "video.generate" : "image.generate"; revisionForm.endpoint = video ? "https://ark.cn-beijing.volces.com/api/v3" : "https://api.openai.com/v1"; revisionForm.channelKind = "official"; revisionForm.capabilitiesJson = video ? JSON.stringify({ inputs: ["text"], outputs: ["video"], resultHosts: ["example.invalid"] }, null, 2) : JSON.stringify({ inputs: ["text"], outputs: ["image"] }, null, 2); }
function resetRevision() { Object.assign(revisionForm, { baseRevisionId: "", providerId: "", providerLabel: "", channelKind: "official", region: "", protocol: "openai_images", endpoint: "https://api.openai.com/v1", credentialRef: "", modelId: "", modelVersion: "v1", operation: "image.generate", creditPrice: null, capabilitiesJson: "{\n  \"inputs\": [\"text\"],\n  \"outputs\": [\"image\"]\n}", costReferenceJson: "{}", currentPassword: "" }); selectedModel.value = null; }
function selectModel(model: Model) { selectedModel.value = model; if (!model.isCurrent) return; Object.assign(revisionForm, { baseRevisionId: model.id, providerId: model.providerId, providerLabel: model.providerLabel, channelKind: model.channelKind, region: model.region, protocol: model.protocol, endpoint: model.endpoint, credentialRef: model.credentialRef, modelId: model.modelId, modelVersion: model.modelVersion, operation: model.operation, creditPrice: model.creditPrice, capabilitiesJson: JSON.stringify(model.capabilities, null, 2), costReferenceJson: JSON.stringify(model.costReference, null, 2), currentPassword: "" }); actionForm.modelRevisionId = model.id; }
function toggleAction() { actionForm.action = actionForm.action === "publish" ? "pause" : "publish"; }
async function loadData() { if (!authorized.value) return; loading.value = true; pageError.value = ""; try { const result = await api<ModelData>("/api/operations/generation/models"); canManage.value = result.canManage; models.value = result.models ?? []; selectedModel.value = selectedModel.value ? models.value.find(item => item.id === selectedModel.value?.id) ?? null : null; if (selectedModel.value?.isCurrent && canManage.value) selectModel(selectedModel.value); if (!actionForm.modelRevisionId && currentModels.value.length) actionForm.modelRevisionId = currentModels.value[0].id; } catch (error) { pageError.value = error instanceof Error ? error.message : "模型配置读取失败。"; } finally { loading.value = false; } }
async function saveRevision() {
  if (savingRevision.value || !revisionForm.currentPassword) return; savingRevision.value = true; pageError.value = ""; pageMessage.value = "";
  try {
    const capabilities = JSON.parse(revisionForm.capabilitiesJson) as unknown; const costReference = JSON.parse(revisionForm.costReferenceJson) as unknown;
    if (!capabilities || typeof capabilities !== "object" || Array.isArray(capabilities) || !costReference || typeof costReference !== "object" || Array.isArray(costReference)) throw new Error("能力和成本依据必须是 JSON 对象。");
    if (revisionForm.creditPrice !== null && (!Number.isSafeInteger(revisionForm.creditPrice) || revisionForm.creditPrice <= 0)) throw new Error("积分价格必须是正整数或留空。");
    const mapping = { providerId: revisionForm.providerId.trim(), providerLabel: revisionForm.providerLabel.trim(), channelKind: revisionForm.channelKind, region: revisionForm.region.trim(), protocol: revisionForm.protocol, endpoint: revisionForm.endpoint.trim(), credentialRef: revisionForm.credentialRef.trim(), modelId: revisionForm.modelId.trim(), modelVersion: revisionForm.modelVersion.trim(), operation: revisionForm.operation, capabilities, costReference, creditPrice: revisionForm.creditPrice, verifiedAt: new Date().toISOString() };
    const result = await api<{ model: { id: string; configVersion: number; published: boolean } }>("/api/operations/generation/models/revision", { method: "POST", body: JSON.stringify({ ...(revisionForm.baseRevisionId ? { baseRevisionId: revisionForm.baseRevisionId } : {}), mapping, currentPassword: revisionForm.currentPassword }) });
    if (!result.model?.id || result.model.published) throw new Error("服务端没有返回未发布映射版本。"); pageMessage.value = `模型映射已保存为配置 v${result.model.configVersion}，尚未发布。`; revisionForm.currentPassword = ""; await loadData(); selectedModel.value = models.value.find(item => item.id === result.model.id) ?? null; if (selectedModel.value) selectModel(selectedModel.value); actionForm.modelRevisionId = result.model.id;
  } catch (error) { pageError.value = error instanceof Error ? error.message : "模型映射保存失败。"; } finally { savingRevision.value = false; }
}
function prepareAction(event: SubmitEvent) { if (savingAction.value) return; const model = currentModels.value.find(item => item.id === actionForm.modelRevisionId); if (!model) { pageError.value = "请选择当前映射版本。"; return; } actionSnapshot.value = { action: actionForm.action, model: { ...model }, reason: actionForm.reason.trim() }; returnFocus.value = event.submitter instanceof HTMLElement ? event.submitter : document.activeElement instanceof HTMLElement ? document.activeElement : null; actionError.value = ""; showConfirm.value = true; void nextTick(() => passwordInput.value?.focus()); }
function closeConfirm() { if (savingAction.value) return; showConfirm.value = false; actionError.value = ""; actionSnapshot.value = null; actionForm.currentPassword = ""; void nextTick(() => returnFocus.value?.focus()); }
function trapFocus(event: KeyboardEvent) { if (event.key !== "Tab" || !dialogRef.value) return; const focusable = [...dialogRef.value.querySelectorAll<HTMLElement>("button:not(:disabled), input:not(:disabled), [href], [tabindex]:not([tabindex='-1'])")]; const first = focusable[0]; const last = focusable.at(-1); if (!first || !last) { event.preventDefault(); dialogRef.value.focus(); } else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }
async function runModelAction() { const snapshot = actionSnapshot.value; if (savingAction.value || !snapshot || !actionForm.currentPassword) return; savingAction.value = true; actionError.value = ""; pageError.value = ""; pageMessage.value = ""; try { const result = await api<{ model: { id: string; configVersion: number; published: boolean } }>(`/api/operations/generation/models/${snapshot.action === "publish" ? "publish" : "pause"}`, { method: "POST", body: JSON.stringify({ modelRevisionId: snapshot.model.id, configVersion: snapshot.model.configVersion, reason: snapshot.reason, currentPassword: actionForm.currentPassword }) }); if (!result.model?.id) throw new Error("服务端没有返回新的映射版本事实。"); showConfirm.value = false; actionForm.currentPassword = ""; actionForm.reason = ""; pageMessage.value = result.model.published ? `服务端已发布模型配置 v${result.model.configVersion}。` : `服务端已停用模型并记录配置 v${result.model.configVersion}。`; actionSnapshot.value = null; await loadData(); const updated = models.value.find(model => model.id === result.model.id); if (updated) selectModel(updated); } catch (error) { actionError.value = error instanceof Error ? error.message : "模型操作未能保存。"; } finally { savingAction.value = false; } }
onMounted(async () => { await session.refresh(); if (!session.user) { await router.replace({ name: "login", query: { next: route.fullPath } }); return; } if (authorized.value) await loadData(); else loading.value = false; });
</script>

<style scoped lang="scss">
.modelOperationsPage {
  .headingActions { display: flex; gap: 8px; }
  .accessNote { margin: 0 0 20px; font-size: 12px; color: var(--cr-text-muted); a { margin-left: 8px; color: var(--cr-text-primary); } }
  .catalogCount { margin: 14px 0 24px; font-size: 12px; color: var(--cr-text-muted); }
  .modelDetail { dl > div { display: grid; grid-template-columns: 100px minmax(0, 1fr); padding: 8px 0; font-size: 13px; } dt { color: var(--cr-text-muted); } dd { margin: 0; overflow-wrap: anywhere; } pre { overflow: auto; font-size: 12px; } summary { cursor: pointer; font-size: 12px; } }
}
